import { html } from "../../../../html.js";
import { useState } from "/prototype/vendor/preact-hooks.js";
import { Icon, Dialog, Tabs } from "../../ui/index.js";
import PageVariants from "../../ui/PageVariants.js";

const spend=[18,25,22,34,31,42,48,55,61,68,72,79];
const models=[['Atlas 3.2','42%','$1.84','94.8%','8.4m'],['Sonnet','31%','$2.12','97.1%','7.1m'],['GPT-5 mini','19%','$0.76','91.4%','5.9m'],['Scout local','8%','$0.09','—','3.2m']];
const runs=[['retry','Add jittered retry policy','Atlas 3.2','$0.82','passed','7m'],['ledger','Reconcile settlement ledger','Sonnet','$1.54','passed','12m'],['webhook','Repair webhook signature fixture','Atlas 3.2','$0.46','failed','9m'],['parser','Fix parser diagnostic spans','GPT-5 mini','$0.31','passed','6m']];
function Line({values=spend,kind=''}){const max=Math.max(...values);const points=values.map((v,i)=>`${i*(300/(values.length-1))},${78-v/max*62}`).join(' ');return html`<svg class=${`p-metrics-line ${kind}`} viewBox="0 0 300 90" role="img" aria-label="Trend line"><path d="M0 78H300"/><polyline points=${points}/>${values.map((v,i)=>html`<circle cx=${i*(300/(values.length-1))} cy=${78-v/max*62} r="2.5"/>`)}</svg>`}
function Toast({message}){return !message?null:html`<div class="p-metrics-toast" role="status">${message}</div>`}
function Toolbar({range,setRange,onExport}){return html`<header class="p-metrics-head"><div><p>OPERATIONS INTELLIGENCE</p><h1>Metrics</h1><span>Decision-grade signals for your autonomous fleet.</span></div><div class="p-metrics-actions"><select aria-label="Time range" value=${range} onChange=${e=>setRange(e.target.value)}><option>Last 30 days</option><option>Last 7 days</option><option>This quarter</option></select><button onClick=${onExport}><${Icon} name="download"/>Export</button></div></header>`}
function Overview(){const[range,setRange]=useState('Last 30 days');const[toast,setToast]=useState('');const[drawer,setDrawer]=useState(false);return html`<section class="p-metrics-wrap"><${Toolbar} range=${range} setRange=${setRange} onExport=${()=>setToast('CSV export is queued')}/><div class="p-metrics-alert"><span>!</span><div><b>Spend is tracking 8% above plan</b><small>Atlas 3.2 retry loops account for most of the variance.</small></div><button onClick=${()=>setDrawer(true)}>Inspect anomaly</button></div><div class="p-metrics-kpis"><article><small>MONTHLY BUDGET</small><strong>$79.20 <em>/ $100</em></strong><div class="p-metrics-meter"><i></i></div><span>Forecast $94.60 · 6d remaining</span></article><article><small>SUCCESS RATE</small><strong>94.8%</strong><span class="good">↑ 2.1 pts from prior period</span></article><article><small>THROUGHPUT</small><strong>184 <em>completed</em></strong><span>6.1 work items / day</span></article><article class="unavailable"><small>TIME TO APPROVAL</small><strong>—</strong><span>Awaiting passkey telemetry</span></article></div><div class="p-metrics-overview-grid"><article class="p-metrics-card p-metrics-burn"><header><div><small>BUDGET BURN-DOWN</small><b>$20.80 available</b></div><button onClick=${()=>setToast('Budget guardrails opened')}>Guardrails</button></header><${Line}/><footer><span>Sep 24</span><span>Today</span><span>Oct 24</span></footer></article><article class="p-metrics-card"><header><div><small>FLEET HEALTH</small><b>Reliable, with one watch item</b></div><i class="p-metrics-live">LIVE</i></header><div class="p-metrics-health"><div><strong>96%</strong><span>CI pass rate</span></div><div><strong>8.4m</strong><span>Median latency</span></div><div><strong>68%</strong><span>Token cache rate</span></div></div><button class="p-metrics-link" onClick=${()=>setToast('Opening CI failures')}>View 3 failing runs →</button></article></div><article class="p-metrics-card p-metrics-suggestions"><header><div><small>OPERATOR SUGGESTIONS</small><b>Two changes could save ~$11.40 this month</b></div></header><div><span class="p-metrics-rank">01</span><p><b>Route documentation tasks to Scout local</b><small>Similar completed work used 62% fewer tokens with no CI impact.</small></p><button onClick=${()=>setToast('Routing rule drafted for review')}>Draft rule</button></div><div><span class="p-metrics-rank">02</span><p><b>Set a retry ceiling for webhook repairs</b><small>Three repeated tool failures drove the current spend spike.</small></p><button onClick=${()=>setToast('Retry ceiling staged')}>Set ceiling</button></div></article>${drawer&&html`<${Dialog} onClose=${()=>setDrawer(false)}><div class="p-metrics-dialog"><small>ANOMALY · ATLAS 3.2</small><h2>Retry cost rose 34%</h2><p>Webhook and retry conversations repeated failed tool calls after CI changes.</p><button onClick=${()=>{setDrawer(false);setToast('A retry ceiling has been staged')}}>Stage retry ceiling</button></div></${Dialog}>`}><${Toast} message=${toast}/></section>`}
function Models(){const[tab,setTab]=useState('Models');const[toast,setToast]=useState('');return html`<section class="p-metrics-wrap p-metrics-lab"><${Toolbar} range="Last 30 days" setRange=${()=>{}} onExport=${()=>setToast('Model comparison exported')}/><${Tabs} value=${tab} setValue=${setTab} items=${['Models','Agents','Organizations']}/><div class="p-metrics-lab-title"><div><p>MODEL ECONOMICS</p><h2>Match capability to the work</h2></div><button onClick=${()=>setToast('Comparison criteria opened')}>Tune comparison</button></div><div class="p-metrics-model-grid">${models.map(([name,share,cost,success,latency],i)=>html`<article class=${i===0?'selected':''}><header><span class="p-metrics-model-mark">${name[0]}</span><div><b>${name}</b><small>${share} of fleet tokens</small></div>${i===0&&html`<em>Recommended</em>`}</header><div class="p-metrics-model-numbers"><span><b>${cost}</b> / PR</span><span><b>${success}</b> success</span><span><b>${latency}</b> latency</span></div><${Line} values=${[8+i*2,15,11+i,22,18+i,30,24,36-i,31,40,35,43]}/><button onClick=${()=>setToast(`${name} routing details opened`)}>Inspect routing →</button></article>`)}</div><article class="p-metrics-card p-metrics-reco"><div><small>WHAT CHANGED</small><h3>Sonnet is outperforming Atlas 3.2 on approval-bound work.</h3><p>Across 28 protected PRs, it reached approval 1.3 minutes sooner with a 2.3 point higher CI pass rate.</p></div><button onClick=${()=>setToast('A safe rollout proposal was created')}>Create rollout</button></article><${Toast} message=${toast}/></section>`}
function Work(){const[filter,setFilter]=useState('All conversations');const[detail,setDetail]=useState(null);const[toast,setToast]=useState('');const shown=filter==='All conversations'?runs:runs.filter(r=>r[4]===filter);return html`<section class="p-metrics-wrap p-metrics-work"><${Toolbar} range="Last 30 days" setRange=${()=>{}} onExport=${()=>setToast('Conversation ledger exported')}/><div class="p-metrics-work-intro"><div><p>CONVERSATION LEDGER</p><h2>See the cost behind every outcome</h2><span>Trace spend, tool pressure, and delivery signals back to a single agent conversation.</span></div><div class="p-metrics-mini"><b>$0.86</b><span>median cost / PR</span></div></div><div class="p-metrics-work-grid"><article class="p-metrics-card p-metrics-funnel"><small>DELIVERY FUNNEL</small><div><b>238</b><span>started</span></div><i></i><div><b>201</b><span>PR opened</span></div><i></i><div><b>184</b><span>merged</span></div><footer>77% reached merge · median 21m</footer></article><article class="p-metrics-card"><small>SUCCESS RATE BY DAY</small><${Line} values=${[88,91,95,92,97,96,94,98,93,95,97]} kind="success"/><footer>Target: 95% · Current: 94.8%</footer></article></div><div class="p-metrics-table-controls"><div class="p-metrics-filter">${['All conversations','passed','failed'].map(x=>html`<button class=${filter===x?'on':''} onClick=${()=>setFilter(x)}>${x}</button>`)}</div><span>${shown.length} conversations</span></div><div class="p-metrics-table" role="table"><div class="p-metrics-tr labels" role="row"><span>CONVERSATION</span><span>MODEL</span><span>COST</span><span>CI</span><span>LATENCY</span></div>${shown.map(r=>html`<button class="p-metrics-tr" role="row" onClick=${()=>setDetail(r)}><span><b>${r[1]}</b><small>#${r[0]}</small></span><span>${r[2]}</span><span>${r[3]}</span><span class=${r[4]}>${r[4]}</span><span>${r[5]}</span></button>`)}</div>${detail&&html`<${Dialog} onClose=${()=>setDetail(null)}><div class="p-metrics-dialog"><small>CONVERSATION DRILL-DOWN</small><h2>${detail[1]}</h2><p>${detail[3]} cost · ${detail[4]} CI · ${detail[5]} end-to-end. Tool retries: 2. Tokens: 18.4k.</p><button onClick=${()=>{setDetail(null);setToast('Transcript opened in Conversations')}}>Open transcript</button></div></${Dialog}>`}><${Toast} message=${toast}/></section>`}
export default function MetricsPage(){return html`<main class="e-page p-metrics-page"><${PageVariants} variants=${[{key:'1',name:'Command center',render:()=>html`<${Overview}/>`},{key:'2',name:'Model lab',render:()=>html`<${Models}/>`},{key:'3',name:'Work ledger',render:()=>html`<${Work}/>`}]}/></main>`;}
